import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { build } from 'vite';

const libDir = path.dirname(fileURLToPath(import.meta.url));
const templatePath = path.join(libDir, 'src/integrations/gpt/bootstrap.template.js');
const bootstrapPath = path.resolve(
  libDir,
  '../../trusted-server-core/src/integrations/gpt_bootstrap.js'
);
const header = `// Generated from trusted-server-js/lib/src/integrations/gpt/bootstrap.template.js
// and publisher_registration.ts. Do not edit this file directly.
// Regenerate: cd crates/trusted-server-js/lib && npm run build:gpt-bootstrap -- --write
`;

/** Render the standalone inline bootstrap with the existing Vite toolchain. */
export async function renderGptBootstrap(entryPath = templatePath) {
  const result = await build({
    configFile: false,
    root: libDir,
    esbuild: { supported: { 'inline-script': true } },
    build: {
      write: false,
      emptyOutDir: false,
      // Object spread already exists in the retained bootstrap. Avoid downlevel
      // helpers outside Rollup's IIFE, which would introduce browser globals.
      target: 'es2018',
      sourcemap: false,
      minify: false,
      rollupOptions: {
        input: entryPath,
        output: { format: 'iife', inlineDynamicImports: true },
      },
    },
    logLevel: 'warn',
  });
  return header + result.output[0].code;
}

/** Refuse stale checked-in output without mutating source or build directories. */
export async function checkGptBootstrap(artifactPath = bootstrapPath) {
  const generated = await renderGptBootstrap();
  if ((await fs.readFile(artifactPath, 'utf8')) !== generated) {
    throw new Error(
      'GPT bootstrap is stale. Run `npm run build:gpt-bootstrap -- --write` in crates/trusted-server-js/lib.'
    );
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const args = process.argv.slice(2);
  if (args.length !== 1 || !['--check', '--write'].includes(args[0])) {
    throw new Error('Usage: node build-gpt-bootstrap.mjs --check|--write');
  }
  if (args[0] === '--write') {
    await fs.writeFile(bootstrapPath, await renderGptBootstrap());
  } else {
    await checkGptBootstrap();
  }
}
